import heapq

def match(orders):
    trades = []
    buy_heap = []  # entries (-price, arrival, id) for active buy orders
    sell_heap = []  # entries (price, arrival, id) for active sell orders
    book = {}  # id -> dict(side, price, qty, status)
    arrival_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book and book[oid]['status'] == 'active' and book[oid]['qty'] > 0:
                book[oid]['status'] = 'cancelled'
            continue

        if typ in ('limit', 'ioc'):
            _, oid, side, price, qty = o
        else:  # market
            _, oid, side, qty = o
            price = None

        arrival_counter += 1
        remaining = qty
        opposite = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and opposite:
            top = opposite[0]
            top_id = top[2]
            top_order = book.get(top_id)

            if top_order is None or top_order['status'] != 'active' or top_order['qty'] <= 0:
                heapq.heappop(opposite)
                continue

            resting_price = top_order['price']

            if typ == 'market':
                cross = True
            else:
                if side == 'buy':
                    cross = price >= resting_price
                else:
                    cross = price <= resting_price

            if not cross:
                break

            trade_qty = min(remaining, top_order['qty'])

            if side == 'buy':
                trades.append([oid, top_id, resting_price, trade_qty])
            else:
                trades.append([top_id, oid, resting_price, trade_qty])

            remaining -= trade_qty
            top_order['qty'] -= trade_qty

            if top_order['qty'] == 0:
                top_order['status'] = 'filled'
                heapq.heappop(opposite)

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'status': 'active'}
            if side == 'buy':
                entry = (-price, arrival_counter, oid)
                heapq.heappush(buy_heap, entry)
            else:
                entry = (price, arrival_counter, oid)
                heapq.heappush(sell_heap, entry)
        elif typ == 'limit' and remaining == 0:
            # fully filled immediately, mark as filled in book for cancel-safety
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'status': 'filled'}
        # ioc/market remainder discarded, nothing to store (cancel on them does nothing anyway)

    return trades

